    counts = {}
    for row in grid:
        for v in row:
            if v != 2:
                counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    colors = {}
    for row in grid:
        for v in row:
            if v not in (2, bg):
                colors[v] = colors.get(v, 0) + 1
    if not colors:
        return [row[:] for row in grid]
    obj = max(colors, key=colors.get)
    coords = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == obj]
    out = [row[:] for row in grid]
    if len(set(cs)) == 1:
        # Vertical boundary: stripe is parallel, on the object's side opposite it.
        boundary_c = cs[0]
        obj_min_c, obj_max_c = min(c for r, c in coords), max(c for r, c in coords)
        stripe_c = obj_min_c - 1 if boundary_c > obj_max_c else obj_max_c + 1
        if 0 <= stripe_c < w:
            for r in range(h):
                out[r][stripe_c] = 8
    elif len(set(rs)) == 1:
        # Horizontal boundary: stripe is parallel, on the object's side opposite it.
