    counts = {}
    for row in grid:
        for value in row:
            if value != 2:
                counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)
    object_counts = {}
    for row in grid:
        for value in row:
            if value not in (2, background):
                object_counts[value] = object_counts.get(value, 0) + 1
    if not object_counts:
        return [row[:] for row in grid]
    obj = max(object_counts, key=object_counts.get)
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == obj]
    out = [row[:] for row in grid]

    if len(marker_rows) == 1:  # horizontal marker; slide object vertically
        mr = next(iter(marker_rows))
        rmin = min(r for r, _ in points)
