            out[r][c] = background
        moved = [(r + shift, c) for r, c in points]
        for r, c in moved:
            out[r][c] = obj
        moved_min = min(r for r, _ in moved)
        moved_max = max(r for r, _ in moved)
        line = moved_max + 1 if mr < moved_min else moved_min - 1
        if 0 <= line < h:
            out[line] = [8] * w

